import ReportActionCompose from '@pages/home/report/ReportActionCompose/ReportActionCompose';
import {withOnyx} from 'react-native-onyx';
import ONYXKEYS from '@src/ONYXKEYS';

jest.mock('@libs/Navigation/Navigation', () => ({
  isFocused: jest.fn().mockReturnValue(true),
  isDrawerOpen: jest.fn().mockReturnValue(false),
}));

const ReportActionComposeWithOnyx = withOnyx({
    session: {
        key: ONYXKEYS.SESSION,
    },
})(ReportActionCompose);

describe('EmojiSuggestions', () of => {
  it('closes the suggestion list after selecting an emoji', async () => {
    const { findByTestId, queryByLabelText, debug } = render(<ReportActionComposeWithOnyx reportID="1" />);
    debug();

    const composer = await findByTestId('composer');
    fireEvent.changeText(composer, ':eye:');

    // Assuming there's a button or some element to select the emoji
    const emojiSuggestion = queryByLabelText('eye');
    fireEvent.press(emojiSuggestion);

    await waitFor(() => {
        const suggestionList = queryByLabelText('Emoji Suggestions');
        expect(suggestionList).toBeNull();
    });
  });
});

